// CLI data adapter only. All configuration/identity/roster/binding policy stays in current native APIs.
internal static class SourceMissionAuthoringTool
{
 static readonly Dictionary<string,string> pins=new Dictionary<string,string>(StringComparer.Ordinal);
 static readonly Dictionary<string,int> maxima=new Dictionary<string,int>(StringComparer.Ordinal);
 static byte[] Read(string path,string expected,int maximum){path=Path.GetFullPath(path);var bytes=ExactInitialValueCodec.ReadFile(path,maximum);string actual=AutonomousWorld.Hash(bytes);if(expected==null||actual!=expected)throw new InvalidDataException("Authoring input hash mismatch: "+path);if(pins.TryGetValue(path,out var prior)&&prior!=actual)throw new InvalidDataException("Mixed authoring input epoch: "+path);pins[path]=actual;maxima[path]=maxima.TryGetValue(path,out int priorMaximum)?Math.Min(priorMaximum,maximum):maximum;return bytes;}
 static JObject Json(byte[] bytes){using var text=new StringReader(Encoding.UTF8.GetString(bytes));using var reader=new JsonTextReader(text){DateParseHandling=DateParseHandling.None};var value=JObject.Load(reader,new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(reader.Read())throw new InvalidDataException("Exactly one complete JSON document required.");return value;}
 static JObject DescriptorFields(JObject request,string name){var value=request[name]as JObject??throw new InvalidDataException("Required authoring descriptor: "+name);if(value.Properties().Count()!=2||value.Properties().Any(x=>x.Name!="path"&&x.Name!="sha256")||value["path"]?.Type!=JTokenType.String||value["sha256"]?.Type!=JTokenType.String)throw new InvalidDataException("Exact path/sha256 descriptor required: "+name);return value;}
 static JObject Descriptor(JObject request,string name,int maximum){var value=DescriptorFields(request,name);return Json(Read((string)value["path"],(string)value["sha256"],maximum));}
 static void Verify(){foreach(var pin in pins)if(AutonomousWorld.Hash(ExactInitialValueCodec.ReadFile(pin.Key,maxima[pin.Key]))!=pin.Value)throw new InvalidDataException("Authoring input changed: "+pin.Key);}
 public static bool TryRun(string[] args,out int code){code=0;if(args.Length==0||args[0]!="--authoring-preflight")return false;try{if(args.Length!=3)throw new ArgumentException("Explicit authoring request and its SHA256 required.");Run(args[1],args[2]);}catch(Exception error){Console.Error.WriteLine(error);code=1;}return true;}
 static void Run(string path,string sha)
 {
  pins.Clear();maxima.Clear();var request=Json(Read(path,sha,1024*1024));
#if WARLINE_SOURCE_DECLARED_COMPILER_EXPORT
  if((string)request["kind"]=="SkirmishDeclaredCompilerExportPreflight"){RunDeclaredCompilerExport(request);return;}
#endif
string[] allowed={"schema_version","kind","catalog_id","seed","size","difficulty","graph","profiles","campaign_source_path","layout","binding","setup_matrix","output_directory","runtime_config","source_repository_root","data_repository_root"};if(request.Properties().Any(x=>!allowed.Contains(x.Name))||(int?)request["schema_version"]!=1||(string)request["kind"]!="SkirmishMissionAuthoringPreflight"||(string)request["catalog_id"]!="S026"||(int?)request["seed"]!=104755)throw new NotSupportedException("Current authoring data scope is S026/104755; autonomous simulation admission is unchanged.");
  if(!Enum.TryParse((string)request["size"],out SkirmishSizeId size)||!Enum.TryParse((string)request["difficulty"],out SkirmishDifficultyId difficulty)||size==SkirmishSizeId.None||difficulty==SkirmishDifficultyId.None)throw new InvalidDataException("Explicit native size and difficulty required.");
  var graph=Descriptor(request,"graph",16*1024*1024);foreach(var pin in((JObject)graph["source_pins"]).Properties())Read(pin.Name,(string)pin.Value,4*1024*1024);var values=new SourceConfigMaterializer(graph);var profiles=request["profiles"]as JObject??throw new InvalidDataException("Explicit actual shared profile paths required.");string[] profileNames={"objective","army","start","economy","upgrades","intel","roles"};if(profiles.Properties().Count()!=profileNames.Length||profiles.Properties().Any(x=>!profileNames.Contains(x.Name)))throw new InvalidDataException("Exact finite profile references required.");
  var source=values.ByPath<OperationMapDefinition>((string)request["campaign_source_path"]);var layout=values.LogicalLayout(Descriptor(request,"layout",1024*1024));if(layout.BindingValueFormat!=SkirmishBindingValueFormat.CanonicalBinaryV2)throw new NotSupportedException("New authoring requires explicit CanonicalBinaryV2 layout field.");bool measuredCandidate=layout.WorldBinding.HasMeasuredDeployments||layout.WorldBinding.BindAllConfigurations;if(measuredCandidate)SourceS026TypedConfiguration.RequireFrozenMeasuredLayout(layout);
  var definition=SourceS026TypedConfiguration.Configure(values,profiles,layout,source);if(request["binding"]!=null){var binding=values.LogicalBinding(Descriptor(request,"binding",2*1024*1024));if(binding.ValueFormat!=layout.BindingValueFormat)throw new InvalidDataException("Authored binding value format differs from layout.");definition.BindMissionLogicalBinding(binding);}
  string directory=Path.GetFullPath((string)request["output_directory"]);if(!Directory.Exists(directory))throw new InvalidDataException("Prepared isolated authoring output directory required.");var matrixDescriptor=DescriptorFields(request,"setup_matrix");var matrix=Read((string)matrixDescriptor["path"],(string)matrixDescriptor["sha256"],4*1024*1024);var catalog=values.ByPath<SkirmishExpansionCatalogConfig>("Assets/Game/Resources/SkirmishExpansionCatalog.asset");UnityEngine.Resources.BindSourceResources(new Dictionary<string,object>{[SkirmishExpansionCatalogConfig.ResourceName]=catalog,[SkirmishSetupMatrixTable.PackagedResourceName]=new UnityEngine.TextAsset(Encoding.UTF8.GetString(matrix))});if(!SkirmishSetupMatrixTable.TryLoadPackaged(out var table,out string matrixError))throw new InvalidDataException(matrixError);
  var runtimeDescriptor=DescriptorFields(request,"runtime_config");string runtimePath=(string)runtimeDescriptor["path"];Read(runtimePath,(string)runtimeDescriptor["sha256"],1024*1024);var before=SourceRuntimeManifest.Write(directory,"before-authoring",runtimePath);
  var manifest=new SkirmishContentManifest{RequiredFeatureIds=definition.RequiredFeatureIds};bool compiled=SkirmishSetupCompiler.TryCompile(definition,difficulty,size,(int)request["seed"],manifest,table,out var setup,out var reasons);bool captured=SkirmishSetupCompiler.TryCaptureMissionLogicalAuthoringInputs(definition,difficulty,size,(int)request["seed"],manifest,table,out var inputs,out var captureReasons);var why=new JArray(reasons.Select(x=>new JObject{["code"]=x.Code.ToString(),["field"]=x.Field,["detail"]=x.Detail}));var result=new JObject{["schema_version"]=1,["kind"]="SkirmishMissionAuthoringPreflightResult",["status"]=compiled?"ConfigurationCompiled":"CompilerRejectedDraft",["catalog_id"]=definition.CatalogId,["seed"]=request["seed"],["size"]=size.ToString(),["difficulty"]=difficulty.ToString(),["value_format"]=(int)layout.BindingValueFormat,["definition_id"]=definition.DefinitionId,["layout_id"]=layout.LayoutId,["operation_map_id"]=source.OperationMapId,["source_content_hash"]=source.ContentHash,["layout_fingerprint"]=SkirmishMeasuredLayoutBinder.ComputeLayoutSemanticFingerprint(layout),["source_fingerprint"]=SkirmishMissionLogicalBindingCompiler.SourceFingerprint(source,layout.BindingValueFormat),["input_pins"]=new JObject(pins.Select(x=>new JProperty(x.Key,new JObject{["sha256"]=x.Value,["maximum_bytes"]=maxima[x.Key]}))),["compiler_accepted"]=compiled,["compiler_reasons"]=why,["native_authoring_inputs_returned"]=captured,["authoring_capture_reasons"]=new JArray(captureReasons.Select(x=>x.ToString())),["world_allocated"]=false,["source_fit_verified"]=false,["mission_ready"]=false,["native_acceptance"]=false,["catalog_mutated"]=false,["native_playable"]=false,["validation_passed"]=false,["scope"]="Current original Configure/TryCompile/TryCapture diagnostics only. Frozen measured geometry is a compiler input, not a physical certificate. No gameplay/source-fit/native/player-readiness claim."};
  if(compiled!=captured||!measuredCandidate&&(compiled||captured))throw new InvalidOperationException("Original compiler/capture consistency changed or unmeasured draft unexpectedly passed.");Verify();File.WriteAllText(Path.Combine(directory,"authoring-result.json"),result.ToString()+Environment.NewLine);var after=SourceRuntimeManifest.Write(directory,"after-authoring",runtimePath);SourceRuntimeManifest.RequireUnchanged(before,after);Console.WriteLine("[SkirmishMissionAuthoringPreflight] status="+result["status"]+" catalog="+definition.CatalogId+" world_allocated=False compiler_accepted="+compiled+" reasons="+reasons.Count);
 }

