 static void RunDeclaredCompilerExport(JObject request){
  string[] allowed={"schema_version","kind","catalog_id","seed","size","difficulty","graph","profiles","campaign_source_path","layout","binding_fields","setup_matrix","metadata_source_origin","output_directory","runtime_config","source_repository_root","data_repository_root","factory_projection_version"};if(request.Properties().Any(x=>!allowed.Contains(x.Name))||(int?)request["schema_version"]!=1)throw new InvalidDataException("Exact declared compiler export request required");
