  var result=SourceDeclaredMissionConfiguration.CompileAndExportSourceInputs(input,(string)request["source_repository_root"]);result["catalog_id"]=request["catalog_id"].DeepClone();result["seed"]=request["seed"].DeepClone();result["world_allocated"]=false;result["source_fit_verified"]=false;result["validation_passed"]=false;result["mission_ready"]=false;result["native_acceptance"]=false;Verify();File.WriteAllText(Path.Combine(directory,"authoring-result.json"),result.ToString()+Environment.NewLine);var after=SourceRuntimeManifest.Write(directory,"after-authoring",(string)runtime["path"]);SourceRuntimeManifest.RequireUnchanged(before,after);Console.WriteLine("[SkirmishDeclaredCompilerExport] result="+result["result"]+" world_allocated=False");
